const d = $input.first().json;
const baseHashtags = '#خدمات_عامة #طلب_خدمة_عامة #2026 #2026 #QualityService #ServiceQuality';
const b2bHashtags = '#خدمات_أعمال #شركة_رائدة #HighQuality #QualityServices #LuxuryTravel #Service2026';

let platformsStr = '';

if (d.platforms) {
  platformsStr = d.platforms;
}
else if (d.platform && d.channel) {
  const p = (d.platform || '').toLowerCase().trim();
  const c = (d.channel || '').toLowerCase().trim();

  if (p === 'x' || p === 'twitter' || c === 'twitter') platformsStr = 'x_twitter';
  else if (p === 'instagram' || c === 'instagram') platformsStr = 'instagram';
  else if (p === 'facebook' || c === 'facebook') platformsStr = 'facebook';
  else if (p === 'whatsapp' || c === 'whatsapp') platformsStr = 'whatsapp';
  else if (p === 'telegram' || c === 'telegram') platformsStr = 'telegram';
  else if (p === 'tiktok' || c === 'tiktok') platformsStr = 'tiktok';
  else if (p === 'linkedin' || c === 'linkedin') platformsStr = 'linkedin';
}
else if (d.content_type === 'b2b' || d.نوع_المحتوى === 'b2b') {
  platformsStr = 'linkedin,facebook,whatsapp,telegram';
}
else {
  platformsStr = 'x_twitter,instagram,facebook,whatsapp,telegram,tiktok';
}

const platforms = platformsStr.split(',').map(p => p.trim()).filter(p => p);


const arTitle = d.ar_title 
  || d.source_title 
  || d.post_text?.split('\n')[0]?.substring(0, 60) 
  || d.x_post?.split('#')[0]?.trim()
  || d.instagram_post?.split('\n')[0]?.substring(0, 60)
  || 'منشور خدمات [COMPANY_NAME]';

const arBody = d.ar_body 
  || d.post_text 
  || d.whatsapp_broadcast 
  || d.instagram_post 
  || d.x_post 
  || '';

const hashtags = d.content_type === 'b2b' ? b2bHashtags : baseHashtags;

return [{
  json: {
    ...d,

    x_final:        (d.x_post || arTitle || '').substring(0, 270),
    ig_final:       (d.instagram_post || arTitle || '') + '\n\n' + hashtags,
    fb_final:       d.facebook_post || d.post_text || arTitle || '',
    wa_final:       d.whatsapp_broadcast || arBody || '',
    tg_final:       (d.telegram_post || arTitle || '') + '\n\n' + hashtags,
    tt_final:       (d.tiktok_caption || d.instagram_post || arTitle || '').substring(0, 200),
    li_final:       d.linkedin_post || d.facebook_post || arBody || '',


    img_text_ar: d.template_text_ar 
      || d.ar_title 
      || d.source_title 
      || (d.post_text || '').split('\n')[0]?.substring(0, 40)
      || (d.x_post || '').split('#')[0]?.trim()?.substring(0, 40)
      || '[COMPANY_NAME] للأتمتة',

    // النص الثانوي (رابط الطلب أو عرض) 
    img_subtext_ar: d.template_subtext_ar 
      || d.order_link 
      || (d.source_url || '').replace('https://', '').split('/')[0]
      || (d.whatsapp_broadcast || '').match(/wa\.me\/(\d+)/)?.[1]
      || '',

    img_prompt_en: d.image_prompt_en 
      || d.image_prompt 
      || 'Professional business environment, golden hour, photorealistic, 16:9',

    post_row_number: d.row_number,
    platforms: platforms,
    publish_start: new Date().toISOString(),

    _debug: {
      content_type: d.content_type,
      original_platform: d.platform,
      original_channel: d.channel,
      detected_platforms: platforms,
      ar_title_used: arTitle.substring(0, 30) + '...',
      hashtags_used: hashtags.substring(0, 20) + '...'
    }
  }
}];

// استخراج رابط الصورة المباشر للنشر (lh3.googleusercontent.com)

try {
  const uploadNode = $('Upload file');
  const prepareNode = $('Code – تحضير المنشور للنشر');

  const postData = prepareNode?.first()?.json || {};
  const uploadData = uploadNode?.first()?.json || {};

  const fileId = uploadData.id || postData.image_file_id;

  if (!fileId) {
    console.error('❌ File ID not found');
    return [{
      json: {
        ...postData,
        image_url: '',
        image_source: 'error',
        image_ready: false,
        image_error: 'File ID not found'
      }
    }];
  }

  const links = {
    // رابط مباشر عالي الجودة (لإنستغرام، فيسبوك، تليجرام)
    direct: `https://lh3.googleusercontent.com/d/${fileId}=w1920-h1080`,

    // رابط مصغر للعرض السريع
    thumbnail: `https://lh3.googleusercontent.com/d/${fileId}=w800-h600`,

    // رابط أصلي للمشاركة اليدوية
    original: `https://drive.google.com/file/d/${fileId}/view?usp=sharing`,

    // رابط للتضمين في المواقع
    embed: `https://drive.google.com/uc?export=view&id=${fileId}`
  };

  console.log('✅ Image URLs generated successfully');
  console.log('Direct URL:', links.direct);

  return [{
    json: {
      ...postData,
      image_url: links.direct,
      image_url_thumbnail: links.thumbnail,
      image_url_original: links.original,
      image_url_embed: links.embed,
      image_file_id: fileId,
      drive_file_id: fileId,
      drive_web_link: uploadData.webViewLink || links.original,
      image_uploaded_at: new Date().toISOString(),
      image_status: 'ready',
      image_source: 'google_drive',
      image_ready: true,
      post_row_number: postData.post_row_number || postData.row_number || ''
    }
  }];

} catch(e) {
  console.error('❌ Error extracting image URL:', e.message);

  const postData = $('Code – تحضير المنشور للنشر')?.first()?.json || {};

  return [{
    json: {
      ...postData,
      image_url: '',
      image_source: 'fallback',
      image_ready: false,
      image_error: e.message,
      post_row_number: postData.post_row_number || ''
    }
  }];
}

const results = $input.all();
const postData = $('Code – تحضير المنشور للنشر').first().json;

const published = [];
const failed    = [];
const errors    = [];

for (const r of results) {
  const d = r.json;
  if (d.id || d.data?.id) published.push('X/Twitter');
  else if (d.success && d.updates) {
    const svc = d.updates?.[0]?.profile_service || 'Buffer';
    published.push(svc.charAt(0).toUpperCase() + svc.slice(1));
  }
  else if (d.messages || d.message_id) published.push('WhatsApp');
  else if (d.ok && d.result) published.push('Telegram');
  else if (d.story_id || d.snapchat_id) published.push('Snapchat');
  else {
    const errMsg = d.error || d.message || JSON.stringify(d).substring(0,100);
    if (errMsg && errMsg.length > 5) {
      failed.push('Unknown');
      errors.push(errMsg);
    }
  }
}

const nowRiyadh = new Date().toLocaleString('ar-SA', {timeZone: 'Asia/Riyadh'});
const total   = published.length + failed.length;
const success = total > 0 ? Math.round((published.length / total) * 100) : 0;

return [{
  json: {
    post_row_number: postData.post_row_number,
    ar_title:        postData.ar_title,
    image_url:       postData.image_url,
    published_on:    published.join(', '),
    failed_on:       failed.join(', '),
    success_count:   published.length,
    failed_count:    failed.length,
    success_rate:    success,
    errors:          errors.join(' | '),
    published_at:    new Date().toISOString()
  }
}];

