const items = $input.all();

function normalizePhone(phone, defaultCountry = '966') {
  if (!phone) return null;

  let clean = String(phone).replace(/[^\d+]/g, '');

  if (clean.startsWith('00')) clean = '+' + clean.slice(2);
  if (clean.startsWith('0') && !clean.startsWith('+')) clean = '+' + defaultCountry + clean.slice(1);

  if (!clean.startsWith('+')) clean = '+' + clean;

  return clean.replace('+', '');
}

function detectCountry(phone) {
  const p = String(phone).replace(/[^\d]/g, '');
  if (p.startsWith('967')) return { code: 'YE', name: 'اليمن', prefix: '967' };
  if (p.startsWith('966')) return { code: 'SA', name: 'السعودية', prefix: '966' };
  if (p.startsWith('20')) return { code: 'EG', name: 'مصر', prefix: '20' };
  if (p.startsWith('971')) return { code: 'AE', name: 'الإمارات', prefix: '971' };
  if (p.startsWith('965')) return { code: 'KW', name: 'الكويت', prefix: '965' };
  if (p.startsWith('974')) return { code: 'QA', name: 'قطر', prefix: '974' };
  if (p.startsWith('973')) return { code: 'BH', name: 'البحرين', prefix: '973' };
  if (p.startsWith('968')) return { code: 'OM', name: 'عُمان', prefix: '968' };
  if (p.startsWith('962')) return { code: 'JO', name: 'الأردن', prefix: '962' };
  if (p.startsWith('961')) return { code: 'LB', name: 'لبنان', prefix: '961' };
  return { code: 'UNKNOWN', name: 'أخرى', prefix: null };
}

return items.map(item => {
  const phone = item.json.phone || item.json.phone_normalized || '';
  const country = detectPhone(phone);
  const normalized = normalizePhone(phone, country.prefix || '966');

  return {
    json: {
      ...item.json,
      phone_normalized: normalized,
      phone_original: phone,
      country_code: country.code,
      country_name: country.name,
      country_prefix: country.prefix,
      is_valid_phone: normalized && normalized.length >= 10 && normalized.length <= 15
    }
  };
});

// تحويل رابط الصورة إلى Binary Data لـ n8n

const item = $input.first().json;
const imageUrl = item.image_url || `https://drive.google.com/uc?export=view&id=${item.image_file_id}`;

return [{
  json: item,
  binary: {
    linkedin_image: {  // ← هذا هو اسم الحقل الذي سنستخدمه
      url: imageUrl,
      fileName: `post_${item.topic_id || Date.now()}.jpg`,
      mimeType: 'image/jpeg'
    }
  }
}];

